// Yesterday's paid orders, counted and totalled
const yesterday = context.yesterday.result;
const orders = (context.orders.items || []).filter((order) => String(order.created_at || "").startsWith(yesterday));
const total = orders.reduce((sum, order) => sum + Number(order.total_price || 0), 0);
return {
  count: orders.length,
  total: total.toFixed(2),
  currency: orders[0] ? orders[0].currency : "",
  list: orders.map((order) => order.name + ": " + order.total_price).join("\n") || "-",
};

